public int countWords(String s) {
    int count = 0;
    boolean inWord = false;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) != ' ') {
            if (!inWord) { count++; inWord = true; }
        } else {
            inWord = false;
        }
    }
    return count;
}
